const { existsSync, readFileSync, readdirSync, statSync } = require("fs");
const { join, relative } = require("path");
const { runSecretScan } = require("./secret-scan");

const root = join(__dirname, "..");

function readText(file) {
  try {
    return readFileSync(join(root, file), "utf8");
  } catch (_) {
    return "";
  }
}

function result(name, status, detail, suggestion) {
  return { name, status, detail, suggestion: suggestion || "" };
}

function hasFile(file) {
  return existsSync(join(root, file));
}

function statusRank(status) {
  if (status === "fail") return 3;
  if (status === "warn") return 2;
  return 1;
}

function overall(results) {
  if (results.some((item) => item.status === "fail")) return "FAIL";
  if (results.some((item) => item.status === "warn")) return "WARN";
  return "PASS";
}

function isSafeDisabledSecretScanFinding(item) {
  const sourceLine = item && item.file && item.line ? String(readText(item.file).split(/\r?\n/)[item.line - 1] || "") : "";
  return item &&
    item.rule === "api-key-assignment" &&
    (/apiKey\s*:\s*"disabled"/.test(item.maskedSnippet || "") || /apiKey\s*:\s*"disabled"/.test(sourceLine));
}

